-- Phase 53: composition layer for role-based personalized workspaces.
alter table public.plans add column if not exists workspace_enabled boolean not null default true,add column if not exists personalized_home_enabled boolean not null default true,add column if not exists workspace_customization_enabled boolean not null default true,add column if not exists workspace_templates_enabled boolean not null default true,add column if not exists display_mode_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists workspace_enabled boolean not null default true,add column if not exists personalized_home_enabled boolean not null default true,add column if not exists workspace_customization_enabled boolean not null default true,add column if not exists workspace_templates_enabled boolean not null default true,add column if not exists display_mode_enabled boolean not null default false;

create table public.workspace_widget_registry(
 id text primary key,title text not null,description text not null,category text not null,widget_type text not null check(widget_type in('metric_card','trend_chart','status_list','task_list','alert_list','progress','leaderboard','table','shortcut_grid','mini_funnel','timeline')),
 size_options jsonb not null default '["small","medium","large"]',required_permissions text[] not null default '{}',supported_scopes text[] not null default '{store}',data_source text not null,refresh_strategy text not null check(refresh_strategy in('realtime','30s','1m','5m','manual','event-driven')),
 configuration_schema jsonb not null default '{}',default_settings jsonb not null default '{}',route text check(route is null or route like '/%'),display_safe boolean not null default false,sensitive boolean not null default false,active boolean not null default true,system_defined boolean not null default true,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.workspace_templates(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,name text not null,target_role text,target_scope text not null check(target_scope in('system','organization','role','store','network')),store_id uuid references public.establishments(id) on delete cascade,
 layout_schema jsonb not null default '[]',active boolean not null default true,version integer not null default 1,rollout_policy text not null default 'merge_required_widgets' check(rollout_policy in('force_replace','merge_required_widgets','suggest_update')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,name,target_role,store_id,version)
);
create table public.workspace_policies(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,role_id text,store_id uuid references public.establishments(id) on delete cascade,user_customization_allowed boolean not null default true,widget_add_allowed boolean not null default true,widget_remove_allowed boolean not null default true,layout_reorder_allowed boolean not null default true,mandatory_widgets text[] not null default '{}',max_widgets integer not null default 16 check(max_widgets between 1 and 40),allowed_widget_categories text[] not null default '{}',workspace_locked boolean not null default false,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,role_id,store_id)
);
create table public.user_workspaces(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role_id text,store_id uuid references public.establishments(id) on delete cascade,name text not null,workspace_type text not null check(workspace_type in('personal','role','store','network','system')),status text not null default 'active' check(status in('draft','active','archived')),is_default boolean not null default false,source text not null check(source in('system_default','organization_template','user_customized')),base_template_id uuid references public.workspace_templates(id) on delete set null,revision integer not null default 1,mode text not null default 'normal' check(mode in('normal','operation')),display_mode boolean not null default false,global_period text not null default 'today',created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create unique index user_workspace_default_idx on public.user_workspaces(organization_id,user_id,coalesce(store_id,'00000000-0000-0000-0000-000000000000'::uuid),workspace_type) where is_default and status='active';
create table public.workspace_widgets(
 id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.user_workspaces(id) on delete cascade,widget_registry_id text not null references public.workspace_widget_registry(id),widget_type text not null,position_x integer not null default 0,position_y integer not null default 0,width integer not null default 1 check(width between 1 and 4),height integer not null default 1 check(height between 1 and 4),config jsonb not null default '{}',order_index integer not null default 0,visible boolean not null default true,pinned_store_id uuid references public.establishments(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,widget_registry_id)
);
create table public.workspace_layout_revisions(
 id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.user_workspaces(id) on delete cascade,revision integer not null,snapshot jsonb not null,change_type text not null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),unique(workspace_id,revision)
);
create table public.workspace_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,workspace_id uuid references public.user_workspaces(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,action text not null,reason text,before_state jsonb,after_state jsonb,correlation_id text not null,created_at timestamptz not null default now());
create table public.workspace_usage_daily(organization_id uuid not null references public.organizations(id) on delete cascade,usage_date date not null,workspace_type text not null,active_users integer not null default 0,customized_users integer not null default 0,widgets_rendered bigint not null default 0,load_failures bigint not null default 0,home_load_ms_sum bigint not null default 0,primary key(organization_id,usage_date,workspace_type));
create table public.widget_performance_hourly(organization_id uuid not null references public.organizations(id) on delete cascade,widget_registry_id text not null references public.workspace_widget_registry(id),bucket_at timestamptz not null,requests bigint not null default 0,errors bigint not null default 0,latency_ms_sum bigint not null default 0,cache_hits bigint not null default 0,query_cost_units bigint not null default 0,health text not null default 'healthy' check(health in('healthy','slow','failing')),primary key(organization_id,widget_registry_id,bucket_at));

