create index workspace_widgets_order_idx on public.workspace_widgets(workspace_id,order_index);create index workspaces_user_idx on public.user_workspaces(organization_id,user_id,store_id,status);create index workspace_templates_resolve_idx on public.workspace_templates(organization_id,target_scope,target_role,store_id,active,version desc);create index widget_performance_health_idx on public.widget_performance_hourly(organization_id,health,bucket_at desc);
do $$ declare t text; begin foreach t in array array['workspace_widget_registry','workspace_templates','workspace_policies','user_workspaces','workspace_widgets','workspace_layout_revisions','workspace_audit_events','workspace_usage_daily','widget_performance_hourly'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
grant select on public.workspace_widget_registry to authenticated;
create policy workspace_widget_registry_read on public.workspace_widget_registry for select to authenticated using(active);
create policy user_workspaces_own_read on public.user_workspaces for select to authenticated using(user_id=(select auth.uid()) and organization_id in(select organization_id from public.organization_members where user_id=(select auth.uid()) and active));
grant select on public.user_workspaces to authenticated;

insert into public.search_navigation_registry(id,title,route,keywords,module,icon,position,customer_visible) values('personal-home','Minha Home','/home',array['workspace','widgets','personalizar','inicio'],'workspace','⌂',1,true) on conflict(id) do update set title=excluded.title,route=excluded.route,keywords=excluded.keywords,module=excluded.module,position=excluded.position;
insert into public.search_command_registry(id,title,description,keywords,command_type,route,required_permission,risk_level,scope,position) values('customize-home','Personalizar minha Home','Adicionar e organizar widgets permitidos',array['workspace','widgets','layout'],'navigation','/home?edit=true','search:global','low','store',1),('restore-workspace','Restaurar workspace','Voltar ao preset da função',array['workspace','restaurar','padrão'],'navigation','/home?restore=true','search:global','medium','store',2) on conflict(id) do update set title=excluded.title,description=excluded.description,route=excluded.route,required_permission=excluded.required_permission,risk_level=excluded.risk_level,position=excluded.position;

create view public.fact_workspace_usage with(security_invoker=true) as select organization_id,usage_date,workspace_type,active_users,customized_users,widgets_rendered,load_failures,home_load_ms_sum from public.workspace_usage_daily;
create view public.fact_widget_performance with(security_invoker=true) as select organization_id,widget_registry_id,bucket_at,requests,errors,latency_ms_sum,cache_hits,query_cost_units,health from public.widget_performance_hourly;
create view public.dim_workspace_type with(security_invoker=true) as select * from(values('personal','Pessoal'),('role','Função'),('store','Unidade'),('network','Rede'),('system','Sistema'))v(workspace_type,label);
create view public.dim_widget_type with(security_invoker=true) as select * from(values('metric_card','Métrica'),('trend_chart','Tendência'),('status_list','Status'),('task_list','Tarefas'),('alert_list','Alertas'),('shortcut_grid','Atalhos'))v(widget_type,label);
revoke all on public.fact_workspace_usage,public.fact_widget_performance,public.dim_workspace_type,public.dim_widget_type from public,anon,authenticated;grant select on public.fact_workspace_usage,public.fact_widget_performance,public.dim_workspace_type,public.dim_widget_type to service_role;
